(在void loop()中) 
void moving(char io,char x,char y){ 
 Wire.beginTransmission(2); //開始傳送，指定給從端2號 (LCD+出口) 
 Wire.write("U"); //給定指令__LCD 顯示Using 
 Wire.endTransmission(); //結束通訊 

 Wire.beginTransmission(1); //開始傳送，指定給從端1號 (xyz) 
 Wire.write(io+x+y); //給定指令__出或進 
 Wire.requestFrom(1,4); //讓從端1號 (xyz)回傳 
 while(Wire.available()){ 
 Serial.print(Wire.readString()); 
 } //接收回傳"done"並輸出 
 Wire.endTransmission(); //結束通訊 
 Wire.beginTransmission(2); //開始傳送，指定給從端2號 (LCD+出口) 
 Wire.write("S"); //給定指令__LCD 顯示Standby 
 Wire.endTransmission(); //結束通訊 
} 

