內容 
#include <Wire.h> //I
2C 函式庫 
#include <SoftwareSerial.h> //序列埠函式庫 

#include <motoLiquidCrystal_I2C.h> //motoduino 的LCD 模組函式庫 

LiquidCrystal_I2C mylcd(0x27,16,2); //初始設定 

void setup(){ 
Wire.begin(2); //I
2C 位址與連線設定，這裡設定為2號 
Serial.begin(9600); //Serial 速率為9600 
//LCD 
 mylcd.init(); 
 mylcd.backlight(); 
 mylcd.clear(); 
 mylcd.setCursor(0,0); 
 mylcd.print("Standby"); 

Wire.onReceive(receiveEvent); //當收到I
2C 訊號時，啟動的動作 
} 

void loop(){ 
 delay(100); //延遲0.1秒 
} 
//自定義的接收後的啟動副程式 
void receiveEvent(int numBytes){ 
 while(Wire.available()){ //判斷Wire.available()有沒有訊號 
 char c = Wire.read(); //將傳入的訊號Wire.read()指定給字串C 
 Serial.print(c); //透過Serial 印出字串C 的內容 
 if(c=='S'){ //收到指令為S，顯示Standby 

 mylcd.clear(); 
 mylcd.setCursor(0,0); 
 mylcd.print("Standby"); 
 } 
 if(c=='U'){ //收到指令為U，顯示Using 
 mylcd.clear(); 
 mylcd.setCursor(0,0); 
 mylcd.print("Using"); 
 } 
 } 
} 

